component.schema:
{
 "description": "AWSAuthEngineRole is the Schema for the awsauthengineroles API",
 "properties": {
  "spec": {
   "description": "AWSAuthEngineRoleSpec defines the desired state of AWSAuthEngineRole",
   "properties": {
    "allowInstanceMigration": {
     "description": "AllowInstanceMigration allows migration of the underlying EC2 instance. EC2 auth only.",
     "type": "boolean"
    },
    "authType": {
     "default": "iam",
     "description": "AuthType specifies the auth type for this role (iam or ec2).",
     "enum": [
      "iam",
      "ec2"
     ],
     "type": "string"
    },
    "authentication": {
     "description": "Authentication is the kube auth configuration to be used to execute this request",
     "properties": {
      "namespace": {
       "description": "Namespace is the Vault namespace to be used in all the operations withing this connection/authentication. Only available in Vault Enterprise.",
       "type": "string"
      },
      "path": {
       "default": "kubernetes",
       "description": "Path is the path of the role used for this kube auth authentication. The operator will try to authenticate at {[namespace/]}auth/{spec.path}",
       "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
       "type": "string"
      },
      "role": {
       "description": "Role the role to be used during authentication",
       "type": "string"
      },
      "serviceAccount": {
       "default": {
        "name": "default"
       },
       "description": "ServiceAccount is the service account used for the kube auth authentication",
       "properties": {
        "name": {
         "default": "",
         "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty. Instances of this type with an empty value here are\nalmost certainly wrong.\nMore info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names/#names",
         "type": "string"
        }
       },
       "type": "object",
       "x-kubernetes-map-type": "atomic"
      }
     },
     "required": [
      "path",
      "role",
      "serviceAccount"
     ],
     "type": "object"
    },
    "boundAccountID": {
     "description": "BoundAccountID constrains EC2 instances to specific account IDs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundAmiID": {
     "description": "BoundAmiID constrains EC2 instances to specific AMI IDs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundEC2InstanceID": {
     "description": "BoundEC2InstanceID constrains to specific EC2 instance IDs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundIAMInstanceProfileARN": {
     "description": "BoundIAMInstanceProfileARN constrains EC2 instances to specific instance profile ARNs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundIAMPrincipalARN": {
     "description": "BoundIAMPrincipalARN constrains IAM auth to specific principal ARNs. Wildcards supported.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundIAMRoleARN": {
     "description": "BoundIAMRoleARN constrains EC2 instances to specific IAM role ARNs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundRegion": {
     "description": "BoundRegion constrains EC2 instances to specific regions.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundSubnetID": {
     "description": "BoundSubnetID constrains EC2 instances to specific subnet IDs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundVpcID": {
     "description": "BoundVpcID constrains EC2 instances to specific VPC IDs.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "connection": {
     "description": "Connection represents the information needed to connect to Vault. This operator uses the standard Vault environment variables to connect to Vault. If you need to override those settings and for example connect to a different Vault instance, you can do with this section of the CR.",
     "properties": {
      "address": {
       "description": "Address Address of the Vault server expressed as a URL and port, for example: https://127.0.0.1:8200/",
       "type": "string"
      },
      "maxRetries": {
       "description": "MaxRetries Maximum number of retries when certain error codes are encountered. The default is 2, for three total attempts. Set this to 0 or less to disable retrying. Error codes that are retried are 412 (client consistency requirement not satisfied) and all 5xx except for 501 (not implemented).",
       "type": "integer"
      },
      "tLSConfig": {
       "properties": {
        "cacert": {
         "description": "Cacert Path to a PEM-encoded CA certificate file on the local disk. This file is used to verify the Vault server's SSL certificate. This environment variable takes precedence over a cert passed via the secret.",
         "type": "string"
        },
        "skipVerify": {
         "description": "SkipVerify Do not verify Vault's presented certificate before communicating with it. Setting this variable is not recommended and voids Vault's security model.",
         "type": "boolean"
        },
        "tlsSecret": {
         "description": "TLSSecret namespace-local secret containing the tls material for the connection. the expected keys for the secret are: ca bundle -\u003e \"ca.crt\", certificate -\u003e \"tls.crt\", key -\u003e \"tls.key\"",
         "properties": {
          "name": {
           "default": "",
           "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty. Instances of this type with an empty value here are\nalmost certainly wrong.\nMore info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names/#names",
           "type": "string"
          }
         },
         "type": "object",
         "x-kubernetes-map-type": "atomic"
        },
        "tlsServerName": {
         "description": "TLSServerName Name to use as the SNI host when connecting via TLS.",
         "type": "string"
        }
       },
       "type": "object"
      },
      "timeOut": {
       "description": "Timeout Timeout variable. The default value is 60s.",
       "type": "string"
      }
     },
     "required": [
      "address"
     ],
     "type": "object"
    },
    "disallowReauthentication": {
     "description": "DisallowReauthentication if true, only allows a single token per instance ID. EC2 auth only.",
     "type": "boolean"
    },
    "inferredAWSRegion": {
     "description": "InferredAWSRegion is the region to search for inferred entities. Required with inferredEntityType.",
     "type": "string"
    },
    "inferredEntityType": {
     "description": "InferredEntityType enables IAM role inferencing. Only valid value: \"ec2_instance\".",
     "type": "string"
    },
    "name": {
     "description": "Name of the role.",
     "type": "string"
    },
    "path": {
     "description": "Path at which to make the configuration.\nThe final path in Vault will be {[spec.authentication.namespace]}/auth/{spec.path}/role/{spec.name}.\nThe authentication role must have the following capabilities = [ \"create\", \"read\", \"update\", \"delete\"] on that path.",
     "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
     "type": "string"
    },
    "policies": {
     "description": "Policies is deprecated — use tokenPolicies instead.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "resolveAWSUniqueIDs": {
     "default": true,
     "description": "ResolveAWSUniqueIDs resolves bound_iam_principal_arn to AWS unique IDs.",
     "type": "boolean"
    },
    "roleTag": {
     "description": "RoleTag enables role tags for EC2 auth. Value is the tag key on the instance.",
     "type": "string"
    },
    "tokenBoundCIDRs": {
     "description": "TokenBoundCIDRs are CIDR blocks that restrict authentication and tie the token.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "tokenExplicitMaxTTL": {
     "description": "TokenExplicitMaxTTL is the hard cap max TTL for tokens.",
     "type": "string"
    },
    "tokenMaxTTL": {
     "description": "TokenMaxTTL is the maximum lifetime for generated tokens.",
     "type": "string"
    },
    "tokenNoDefaultPolicy": {
     "description": "TokenNoDefaultPolicy if true, omits the default policy from generated tokens.",
     "type": "boolean"
    },
    "tokenNumUses": {
     "description": "TokenNumUses is the max number of times a token may be used (0 = unlimited).",
     "format": "int64",
     "minimum": 0,
     "type": "integer"
    },
    "tokenPeriod": {
     "description": "TokenPeriod is the maximum allowed period for periodic tokens.",
     "format": "int64",
     "minimum": 0,
     "type": "integer"
    },
    "tokenPolicies": {
     "description": "TokenPolicies are policies to encode onto generated tokens.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "tokenTTL": {
     "description": "TokenTTL is the incremental lifetime for generated tokens.",
     "type": "string"
    },
    "tokenType": {
     "description": "TokenType is the type of token to generate (service, batch, default).",
     "enum": [
      "service",
      "batch",
      "default",
      "default-service",
      "default-batch"
     ],
     "type": "string"
    }
   },
   "required": [
    "authentication",
    "name",
    "path"
   ],
   "type": "object"
  }
 },
 "title": "AWS Auth Engine Role",
 "type": "object"
}
